using BotFramework.Discord.Commands;using BotFramework.Discord.Routing;using Games.Meta.Application.Meta;
namespace Games.Meta.Discord;
public sealed class MetaDiscordHandler(IMetaService service):IDiscordMessageHandler{public bool CanHandle(DiscordMessageContext context)=>DiscordCommand.Is(context,"profile","season","metatop","achievements","streaks");public async Task HandleAsync(DiscordMessageContext context){var cmd=DiscordCommand.Parts(context)[0].ToLowerInvariant();var scope=DiscordCommand.ScopeId(context);var uid=DiscordCommand.UserId(context);object r=cmd switch{"season"=>await service.GetActiveSeasonAsync(context.CancellationToken),"metatop"=>await service.GetTopAsync(scope,10,context.CancellationToken),"achievements"=>await service.GetAchievementsAsync(scope,uid,context.CancellationToken),"streaks"=>await service.GetGameStreaksAsync(scope,uid,context.CancellationToken),_=>await service.GetProfileAsync(scope,uid,DiscordCommand.DisplayName(context),context.CancellationToken)};await DiscordCommand.ReplyResultAsync(context,r,"Meta");}}
